// Interface language: `t(english)` gives the Hindi when the language is Hindi and a translation exists, the English otherwise;
// the choice is saved and sets <html lang>. hi.json is generated by scripts/translate_ui_hi.py (no hand edits).
import fs from "node:fs";
import path from "node:path";
import { act, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it } from "vitest";
import { I18nProvider, translate, useLang, useT } from "@/lib/i18n";
import hi from "@/lib/i18n/hi.json";
import source from "@/lib/i18n/source.en.json";

const HI = hi as Record<string, string>;
const DEVANAGARI = /[ऀ-ॿ]/;

function Probe() {
  const t = useT();
  const { lang, setLang } = useLang();
  return (
    <div>
      <p data-testid="text">{t("Review facts")}</p>
      <p data-testid="missing">{t("A string with no translation anywhere")}</p>
      <button onClick={() => setLang(lang === "hi" ? "en" : "hi")}>toggle</button>
    </div>
  );
}

afterEach(() => {
  window.localStorage.clear();
  document.documentElement.lang = "en";
});

describe("translate", () => {
  it("returns the English in English and for a string with no translation", () => {
    expect(translate("Review facts", "en")).toBe("Review facts");
    expect(translate("A string with no translation anywhere", "hi")).toBe("A string with no translation anywhere");
  });
  it("returns the Hindi when there is one", () => {
    expect(translate("Review facts", "hi")).toBe(HI["Review facts"]);
    expect(HI["Review facts"]).toMatch(DEVANAGARI);
  });
});

describe("I18nProvider", () => {
  it("starts in English, switches to Hindi, saves the choice and sets the page language", () => {
    render(<I18nProvider><Probe /></I18nProvider>);
    expect(screen.getByTestId("text").textContent).toBe("Review facts");
    act(() => screen.getByText("toggle").click());
    expect(screen.getByTestId("text").textContent).toBe(HI["Review facts"]);
    expect(screen.getByTestId("missing").textContent).toBe("A string with no translation anywhere");
    expect(document.documentElement.lang).toBe("hi");
    expect(window.localStorage.getItem("vs-lang")).toBe("hi");
  });
  it("reads a saved Hindi choice after mount", () => {
    window.localStorage.setItem("vs-lang", "hi");
    render(<I18nProvider><Probe /></I18nProvider>);
    expect(screen.getByTestId("text").textContent).toBe(HI["Review facts"]);
  });
  it("is English with no provider", () => {
    render(<Probe />);
    expect(screen.getByTestId("text").textContent).toBe("Review facts");
  });
});

describe("the generated table", () => {
  const strings = source as string[];
  it("covers every interface string with Hindi text that keeps its placeholders", () => {
    const missing = strings.filter((s) => !HI[s]);
    expect(missing, "run scripts/translate_ui_hi.py").toEqual([]);
    for (const s of strings) {
      const letters = s.replace(/\{[^{}]*\}/g, "").replace(/[^A-Za-z]/g, "");
      if (letters.length > 4) expect(HI[s], s).toMatch(DEVANAGARI);
      expect((HI[s].match(/\{[^{}]*\}/g) ?? []).sort(), s).toEqual((s.match(/\{[^{}]*\}/g) ?? []).sort());
    }
  });
  it("lists every literal passed to t() in the components (source.en.json is current)", () => {
    const root = path.resolve(__dirname, "../..");
    const found = new Set<string>();
    const walk = (dir: string) => {
      for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        const p = path.join(dir, e.name);
        if (e.isDirectory()) walk(p);
        else if (/\.(ts|tsx)$/.test(e.name)) for (const m of fs.readFileSync(p, "utf8").matchAll(/\bt\(\s*"((?:[^"\\\n]|\\.)*)"\s*\)/g)) found.add(JSON.parse(`"${m[1]}"`));
      }
    };
    for (const d of ["components", "lib", "app"]) walk(path.join(root, d));
    expect([...found].filter((s) => !strings.includes(s)), "run scripts/extract-ui-strings.ts").toEqual([]);
  });
});
